-file("src/data/recharge_data.erl", 1).

-module(recharge_data).

-export([charge/1,
         gold/1,
         get_present_reward/1,
         get_gift/1,
         get_turn/0,
         turn_score/1,
         get_charge_three_times/1,
         get_ios_recharge_data/1]).

-file("inc/common.hrl", 1).

-type p() :: bitstring().

-type z() :: non_neg_integer().

-type role_id() :: {pos_integer(), p(), z()}.

-type unit_id() :: {pos_integer(), pos_integer()}.

-type pos() :: {pos_integer(),
                non_neg_integer(),
                non_neg_integer()}.

-record(center,
        {ready = 0 :: 1 | 0,
         pid :: undefined | pid(),
         node :: undefined | atom(),
         center_platform = "" :: list(),
         center_zone_id = 0 :: non_neg_integer(),
         platform = <<>> :: bitstring(),
         zone_id = 0 :: non_neg_integer(),
         combine = [] :: [{bitstring(), non_neg_integer()}]}).

-record(notice_rec,
        {type = 11, digit_attr = [], str_attr = []}).

-file("src/data/recharge_data.erl", 23).

-file("inc/charge_gift.hrl", 1).

-record(m_charge_gift,
        {ver = 1,
         flag = 0,
         login_time = 0,
         check_time = 0,
         start_time = 0,
         keep_time = 0,
         pay_time = 0,
         end_time = 0,
         check_time_list = [],
         acc = 0,
         return = 0,
         num = 0,
         list = []}).

-record(charge_gift_data,
        {min = 0,
         max = 0,
         group = 0,
         gold = 0,
         charge_gold = 0,
         num = 0,
         list = [],
         title = "",
         msg = ""}).

-record(charge_gift_server, {white = [], black = []}).

-file("src/data/recharge_data.erl", 24).

-file("inc/pay_turn.hrl", 1).

-record(m_pay_turn, {lucky = 0, list = []}).

-record(pay_turn_data,
        {id = 0,
         item_id = 0,
         bind = 0,
         num = 0,
         type = 0,
         sex = 0,
         classes = 0,
         min_lev = 0,
         max_lev = 0,
         min_lev_break = 0,
         max_lev_break = 0,
         is_cast = 0,
         lucky = 0,
         reset_lucky = 0,
         must = 0,
         min_lucky = 0,
         max_lucky = 0,
         weigth = 0}).

